from pathlib import Path
import re, statistics
for page in [19,20]:
    txt=Path(f'tmp/pdfs/page-{page:02d}.txt').read_text().split('Table '+str(11 if page==19 else 13)+':')[0]
    nums_by_method={'G-Eval': [], 'CheckEval': []}
    print('PAGE',page)
    for line in txt.splitlines():
        vals=[float(x) for x in re.findall(r'-?\\d+\\.\\d{4}',line)]
        if len(vals)"'!=10:
            continue
        modelpart=re.split(r'"'-?\\d+\\.\\d{4}',line)[0].strip()
        expected=[statistics.mean(vals[:8:2]),statistics.mean(vals[1:8:2])]
        if max(abs(expected[i]-vals[8+i]) for i in [0,1])>.00011:
            print('INCONSISTENT', modelpart, 'printed',vals[-2:],'computed',expected)
        for method in nums_by_method:
            if method in modelpart:
                nums_by_method[method].append(vals[-2:])
    for method, vals in nums_by_method.items():
        print(method, 'count',len(vals),'metric means',[statistics.mean(x[i] for x in vals) for i in [0,1]], 'variances',[statistics.variance(x[i] for x in vals) for i in [0,1]])
